/**
 * Ambient module declarations for the two first-party Contentful seed scripts under
 * scripts/contentful/ that a .test.tsx imports to prove their entries stay in sync with the
 * component copy they mirror (see zimmCountryLanguageMismatch/index.test.tsx and
 * zimmDrawer/index.test.tsx). Plain .mjs, deliberately outside overrides/'s TypeScript surface
 * (scripts/ is its own toolchain — see AGENTS.md's "TypeScript only inside overrides/" rule), so
 * — same mechanism as vendor.d.ts's own untyped-package declarations, just for a first-party
 * reason instead of a third-party one — this hand-writes the one shape each script actually
 * exports rather than leaving the import unresolved.
 */
declare module '~/scripts/contentful/seedRegionalPromptUiCopy.mjs' {
  export const ENTRIES: { key: string; title: string; value: string; description: string }[];
}

declare module '~/scripts/contentful/seedDrawerCloseUiCopy.mjs' {
